// Bit-exact AV1 loop-restoration FULL-FRAME (single plane) HIGH-BIT-DEPTH
// verification (10/12-bit), the bd-aware sibling of lr_frame_test.dart.
//
//  (A) bd-aware inline golden `_goldPlane` vs the REAL SW oracle
//      `sw.applyRestorationPlane(..., bd)` at production constants
//      (procUnitSize=64, unitOffset=8), pure Dart, no HW. Proves the golden's
//      bd rounding (Wiener round_0/round_1 12-bit bump + clampLimit, SGR calc_ab
//      >>2*(bd-8)/>>(bd-8), clip_pixel_highbd, the int16 projection truncation)
//      is bit-identical to libaom's port at 10 and 12 bit.
//
//  (B) HARBOR HW `HarborLrFrame(bd: ...)` vs the bd-aware `_goldPlane` at tiny
//      procUnitSize/unitOffset (a handful of stripes). Covers a Wiener unit and
//      an SGR unit (all three sgr_params regimes: r0>0&r1>0, r0==0, r1==0),
//      luma and 4:2:0 chroma, at bd 10 and 12.
//
//  (C) 4:2:2 chroma geometry (ssX=1, ssY=0) at 8-bit vs the golden, confirming
//      the walk has no 4:2:0 hardcode.

({int round0, int round1}) _wienerRounds(int bd) {
  var round0 = 3;
  var round1 = 2 * 7 - round0; // 11
  final intbufrange = bd + 7 - round0 + 2;
  if (intbufrange > 16) {
    round0 += intbufrange - 16;
    round1 -= intbufrange - 16;
  }
  return (round0: round0, round1: round1);
}

int _horz(List<int> p, int t0, int t1, int t2, int bd) {
  final r = _wienerRounds(bd);
  final clampLimit = 1 << (bd + 1 + 7 - r.round0);
  final tc = -2 * (t0 + t1 + t2);
  final sum =
      t0 * (p[0] + p[6]) + t1 * (p[1] + p[5]) + t2 * (p[2] + p[4]) + tc * p[3];
  final rounding = (p[3] << 7) + (1 << (bd + 7 - 1));
  var val = (sum + rounding + (1 << (r.round0 - 1))) >> r.round0;
  if (val < 0) val = 0;
  if (val > clampLimit - 1) val = clampLimit - 1;
  return val;
}

int _vert(List<int> m, int t0, int t1, int t2, int bd) {
  final r = _wienerRounds(bd);
  final hi = (1 << bd) - 1;
  final tc = -2 * (t0 + t1 + t2);
  final sum =
      t0 * (m[0] + m[6]) + t1 * (m[1] + m[5]) + t2 * (m[2] + m[4]) + tc * m[3];
  final rounding = (m[3] << 7) - (1 << (bd + r.round1 - 1));
  final val = (sum + rounding + (1 << (r.round1 - 1))) >> r.round1;
  return val < 0 ? 0 : (val > hi ? hi : val);
}

int _wiener2d(List<List<int>> r, List<int> h, List<int> v, int bd) {
  final mid = [
    for (var row = 0; row < 7; row++) _horz(r[row], h[0], h[1], h[2], bd),
  ];
  return _vert(mid, v[0], v[1], v[2], bd);
}

int _round2(int x, int n) => n == 0 ? x : (x + (1 << (n - 1))) >> n;
int _round2u(int x, int n) => n == 0 ? x : (x + (1 << (n - 1))) >> n;
int _clipHbd(int v, int bd) {
  final hi = (1 << bd) - 1;
  return v < 0 ? 0 : (v > hi ? hi : v);
}

({List<List<int>> a, List<List<int>> b}) _ab(
  List<int> padded,
  int pw,
  int r,
  int width,
  int height,
  int s,
  int bd,
) {
  final gw = width + 2, gh = height + 2;
  final win = 2 * r + 1;
  final n = win * win;
  final recip = HarborSgrCalcAb.oneByX[n - 1];
  int padAt(int row, int col) => padded[row * pw + col];
  final a = List.generate(gh, (_) => List<int>.filled(gw, 0));
  final b = List.generate(gh, (_) => List<int>.filled(gw, 0));
  for (var ci = 0; ci < gh; ci++) {
    for (var cj = 0; cj < gw; cj++) {
      var avRaw = 0, bvRaw = 0;
      for (var dr = 0; dr < win; dr++) {
        for (var dc = 0; dc < win; dc++) {
          final p = padAt(ci + dr, cj + dc);
          bvRaw += p;
          avRaw += p * p;
        }
      }
      // bd rounding: p/z path uses rounded box-sums, b uses the original sum.
      final av = _round2u(avRaw, 2 * (bd - 8));
      final bv = _round2u(bvRaw, bd - 8);
      final pp = (av * n < bv * bv) ? 0 : av * n - bv * bv;
      final z = _round2u(pp * s, 20);
      final ai = HarborSgrCalcAb.xByXPlus1[z > 255 ? 255 : z];
      a[ci][cj] = ai;
      b[ci][cj] = _round2u((256 - ai) * bvRaw * recip, 12);
    }
  }
  return (a: a, b: b);
}

List<int> _goldFast(
  List<int> padded,
  int pw,
  int r,
  int width,
  int height,
  int s,
  int bd,
) {
  final g = _ab(padded, pw, r, width, height, s, bd);
  final a = g.a, b = g.b;
  final out = <int>[];
  for (var i = 0; i < height; i++) {
    for (var j = 0; j < width; j++) {
      int ag(int dr, int dc) => a[i + dr][j + dc];
      int bg(int dr, int dc) => b[i + dr][j + dc];
      final center = padded[(i + r + 1) * pw + (j + r + 1)];
      if (i.isEven) {
        final av =
            (ag(0, 1) + ag(2, 1)) * 6 +
            (ag(0, 0) + ag(0, 2) + ag(2, 0) + ag(2, 2)) * 5;
        final bv =
            (bg(0, 1) + bg(2, 1)) * 6 +
            (bg(0, 0) + bg(0, 2) + bg(2, 0) + bg(2, 2)) * 5;
        out.add(_round2(av * center + bv, 9));
      } else {
        final av = ag(1, 1) * 6 + (ag(1, 0) + ag(1, 2)) * 5;
        final bv = bg(1, 1) * 6 + (bg(1, 0) + bg(1, 2)) * 5;
        out.add(_round2(av * center + bv, 8));
      }
    }
  }
  return out;
}

List<int> _goldFull(
  List<int> padded,
  int pw,
  int r,
  int width,
  int height,
  int s,
  int bd,
) {
  final g = _ab(padded, pw, r, width, height, s, bd);
  final a = g.a, b = g.b;
  final out = <int>[];
  for (var i = 0; i < height; i++) {
    for (var j = 0; j < width; j++) {
      int ag(int dr, int dc) => a[i + dr][j + dc];
      int bg(int dr, int dc) => b[i + dr][j + dc];
      final av =
          (ag(1, 1) + ag(1, 0) + ag(1, 2) + ag(0, 1) + ag(2, 1)) * 4 +
          (ag(0, 0) + ag(0, 2) + ag(2, 0) + ag(2, 2)) * 3;
      final bv =
          (bg(1, 1) + bg(1, 0) + bg(1, 2) + bg(0, 1) + bg(2, 1)) * 4 +
          (bg(0, 0) + bg(0, 2) + bg(2, 0) + bg(2, 2)) * 3;
      final center = padded[(i + r + 1) * pw + (j + r + 1)];
      out.add(_round2(av * center + bv, 9));
    }
  }
  return out;
}

List<int> _goldProc(
  List<int> padded,
  int width,
  int height,
  int s0,
  int s1,
  int xq0,
  int xq1,
  int bd,
) {
  final pw = width + 6;
  final flt0 = _goldFast(padded, pw, 2, width, height, s0, bd);
  final sw2 = width + 4, sh = height + 4;
  final sub = <int>[
    for (var r = 1; r < 1 + sh; r++)
      for (var c = 1; c < 1 + sw2; c++) padded[r * pw + c],
  ];
  final flt1 = _goldFull(sub, sw2, 1, width, height, s1, bd);
  final out = <int>[];
  for (var i = 0; i < height; i++) {
    for (var j = 0; j < width; j++) {
      final k = i * width + j;
      final pre = padded[(i + 3) * pw + (j + 3)];
      final u = pre << 4;
      var v = pre << 11;
      v += xq0 * (flt0[k] - u);
      v += xq1 * (flt1[k] - u);
      // libaom stores the projection in an int16_t before clip_pixel_highbd.
      final outw = _round2(v, 11).toSigned(16);
      out.add(_clipHbd(outw, bd));
    }
  }
  return out;
}

List<int> _goldUnit(
  List<int> padded,
  int pw,
  int w,
  int h,
  int rtype,
  List<int> hf,
  List<int> vf,
  int s0,
  int s1,
  int xq0,
  int xq1,
  int bd,
) {
  if (rtype == 0) {
    final out = <int>[];
    for (var i = 0; i < h; i++) {
      for (var j = 0; j < w; j++) {
        out.add(padded[(i + 3) * pw + (j + 3)]);
      }
    }
    return out;
  } else if (rtype == 1) {
    final out = <int>[];
    for (var i = 0; i < h; i++) {
      for (var j = 0; j < w; j++) {
        final win = [
          for (var r = 0; r < 7; r++)
            [for (var c = 0; c < 7; c++) padded[(i + r) * pw + (j + c)]],
        ];
        out.add(_wiener2d(win, hf, vf, bd));
      }
    }
    return out;
  } else {
    return _goldProc(padded, w, h, s0, s1, xq0, xq1, bd);
  }
}

int _countUnits(int unitSize, int planeSize) =>
    max((planeSize + (unitSize >> 1)) ~/ unitSize, 1);

List<List<int>> _goldPlane(
  List<List<int>> postCdef,
  List<List<int>> deblocked,
  int planeW,
  int planeH,
  int unitSize,
  int ssX,
  int ssY,
  int procUnitSize,
  int unitOffset,
  int bd,
  List<int> rtypes,
  List<List<int>> hf,
  List<List<int>> vf,
  List<int> s0,
  List<int> s1,
  List<int> xq0,
  List<int> xq1,
) {
  final horzUnits = _countUnits(unitSize, planeW);
  final out = [for (var y = 0; y < planeH; y++) List<int>.filled(planeW, 0)];

  int clampX(int c) => c < 0 ? 0 : (c >= planeW ? planeW - 1 : c);
  int clampY(int r) => r < 0 ? 0 : (r >= planeH ? planeH - 1 : r);
  int postAt(int row, int col) => postCdef[clampY(row)][clampX(col)];
  int deblockAt(int row, int col) => deblocked[clampY(row)][clampX(col)];

  final stripeHeight = procUnitSize >> ssY;
  final stripeOff = unitOffset >> ssY;
  final procunitWidth = procUnitSize >> ssX;
  final runitOffset = stripeOff;
  final voffset = stripeOff;
  final extSize = unitSize * 3 ~/ 2;

  int boundaryAbove(int stripe, int ctx, int col) {
    final y0 = max(0, stripe * stripeHeight - stripeOff);
    if (stripe > 0) {
      final row = y0 - 2;
      final lines = min(2, planeH - row);
      final r = ctx == 0 ? row : (lines >= 2 ? row + 1 : row);
      return deblockAt(r, col);
    }
    return postAt(y0, col);
  }

  int boundaryBelow(int stripe, int ctx, int col) {
    final y1 = min((stripe + 1) * stripeHeight - stripeOff, planeH);
    if (y1 < planeH) {
      final row = y1;
      final lines = min(2, planeH - row);
      final r = ctx == 0 ? row : (lines >= 2 ? row + 1 : row);
      return deblockAt(r, col);
    }
    return postAt(y1 - 1, col);
  }

  void emitBlock(
    int unitIdx,
    int colStart,
    int rowStart,
    int w,
    int h,
    int frameStripe,
    bool copyAbove,
    bool copyBelow,
  ) {
    final pw = w + 6, ph = h + 6;
    final padded = List<int>.filled(pw * ph, 0);
    for (var r = 0; r < ph; r++) {
      final bodyRel = r - 3;
      for (var c = 0; c < pw; c++) {
        final planeCol = colStart + c - 3;
        int px;
        if (bodyRel >= 0 && bodyRel < h) {
          px = postAt(rowStart + bodyRel, planeCol);
        } else if (bodyRel < 0) {
          if (copyAbove) {
            final ctx = bodyRel + 2 <= 0 ? 0 : 1;
            px = boundaryAbove(frameStripe, ctx, planeCol);
          } else {
            px = postAt(rowStart + bodyRel, planeCol);
          }
        } else {
          if (copyBelow) {
            final i = bodyRel - h;
            final ctx = i < 1 ? 0 : 1;
            px = boundaryBelow(frameStripe, ctx, planeCol);
          } else {
            px = postAt(rowStart + bodyRel, planeCol);
          }
        }
        padded[r * pw + c] = px;
      }
    }
    final uo = _goldUnit(
      padded,
      pw,
      w,
      h,
      rtypes[unitIdx],
      hf[unitIdx],
      vf[unitIdx],
      s0[unitIdx],
      s1[unitIdx],
      xq0[unitIdx],
      xq1[unitIdx],
      bd,
    );
    for (var i = 0; i < h; i++) {
      for (var j = 0; j < w; j++) {
        out[rowStart + i][colStart + j] = uo[i * w + j];
      }
    }
  }

  void filterUnit(int unitIdx, int hStart, int hEnd, int vStart, int vEnd) {
    final unitH = vEnd - vStart, unitW = hEnd - hStart;
    var i = 0;
    while (i < unitH) {
      final stripeVStart = vStart + i;
      var copyAbove = true, copyBelow = true;
      final firstInPlane = stripeVStart == 0;
      final thisStripeHeight = stripeHeight - (firstInPlane ? runitOffset : 0);
      final lastInPlane = stripeVStart + thisStripeHeight >= planeH;
      if (firstInPlane) copyAbove = false;
      if (lastInPlane) copyBelow = false;
      final frameStripe = (stripeVStart + runitOffset) ~/ stripeHeight;
      final nominal = stripeHeight - (frameStripe == 0 ? runitOffset : 0);
      final h = min(nominal, vEnd - stripeVStart);
      var jj = 0;
      while (jj < unitW) {
        final w = min(procunitWidth, unitW - jj);
        emitBlock(
          unitIdx,
          hStart + jj,
          stripeVStart,
          w,
          h,
          frameStripe,
          copyAbove,
          copyBelow,
        );
        jj += w;
      }
      i += h;
    }
  }

  var y0 = 0, rowNum = 0;
  while (y0 < planeH) {
    final remainingH = planeH - y0;
    final hUnit = remainingH < extSize ? remainingH : unitSize;
    var vStart = y0, vEnd = y0 + hUnit;
    vStart = max(0, vStart - voffset);
    if (vEnd < planeH) vEnd -= voffset;
    var x0 = 0, jcol = 0;
    while (x0 < planeW) {
      final remainingW = planeW - x0;
      final wUnit = remainingW < extSize ? remainingW : unitSize;
      final unitIdx = rowNum * horzUnits + jcol;
      filterUnit(unitIdx, x0, x0 + wUnit, vStart, vEnd);
      x0 += wUnit;
      jcol++;
    }
    y0 += hUnit;
    rowNum++;
  }
  return out;
}

List<int> _decodeXq(List<int> xqd, List<List<int>> params) {
  if (params[0][0] == 0) return [0, (1 << 7) - xqd[1]];
  if (params[0][1] == 0) return [xqd[0], 0];
  return [xqd[0], (1 << 7) - xqd[0] - xqd[1]];
}

BigInt _packPlane(List<List<int>> plane, int planeW, int planeH, int bd) {
  var packed = BigInt.zero;
  var k = 0;
  for (var r = 0; r < planeH; r++) {
    for (var c = 0; c < planeW; c++) {
      packed |= BigInt.from(plane[r][c]) << (k * bd);
      k++;
    }
  }
  return packed;
}

// Per-unit coefficient generation shared by golden + HW. `eps`, when given,
// forces the SGR entropy-parameter index cycle (to sweep the sgr_params regimes
// r0>0&r1>0, r0==0, r1==0), `forceRt` forces the restoration type.
class _Units {
  final List<int> rtypes;
  final List<List<int>> hf;
  final List<List<int>> vf;
  final List<int> s0;
  final List<int> s1;
  final List<int> xq0;
  final List<int> xq1;
  final List<int> ep; // chosen sgr entropy-param index (-1 if not sgr)
  final List<List<int>> xqd; // signalled sgr weights (for the SW LrPlane)
  _Units(
    this.rtypes,
    this.hf,
    this.vf,
    this.s0,
    this.s1,
    this.xq0,
    this.xq1,
    this.ep,
    this.xqd,
  );
}

// Projection weights the HW xq0/xq1 ports (8b signed, [-128,127]) can carry.
// libaom's decode_xq general-case xq1 = 128 - xqd0 - xqd1 can reach 256, which
// is outside the 8b-signed HW contract, the HW cases therefore draw xq from
// these in-range lists (mirroring lr_frame_test's HW harness) while still
// selecting the sgr ep per regime for the s0/s1 noise. The pure-Dart Tier A
// uses full decode_xq (width-agnostic) to validate the golden against the SW
// oracle across the entire xq range.
const _xq0Vals = [-96, -64, -32, 0, 16, 31];
const _xq1Vals = [-32, 0, 16, 48, 95];

_Units _genUnits(
  Random rng,
  int numUnits, {
  List<int>? eps,
  int? forceRt,
  bool hwSafeXq = false,
}) {
  final rtypes = <int>[], hf = <List<int>>[], vf = <List<int>>[];
  final s0 = <int>[], s1 = <int>[], xq0 = <int>[], xq1 = <int>[];
  final epOut = <int>[], xqd = <List<int>>[];
  var epc = 0;
  for (var u = 0; u < numUnits; u++) {
    final rt = forceRt ?? rng.nextInt(3);
    if (rt == 1) {
      rtypes.add(1);
      hf.add([rng.nextInt(16) - 5, rng.nextInt(32) - 23, rng.nextInt(64) - 17]);
      vf.add([rng.nextInt(16) - 5, rng.nextInt(32) - 23, rng.nextInt(64) - 17]);
      s0.add(0);
      s1.add(0);
      xq0.add(0);
      xq1.add(0);
      epOut.add(-1);
      xqd.add([0, 0]);
    } else if (rt == 2) {
      final ep = eps != null ? eps[epc++ % eps.length] : rng.nextInt(16);
      final params = _av1SgrParams[ep];
      rtypes.add(2);
      hf.add([0, 0, 0]);
      vf.add([0, 0, 0]);
      s0.add(params[0][0] > 0 ? params[1][0] : 0);
      s1.add(params[0][1] > 0 ? params[1][1] : 0);
      if (hwSafeXq) {
        // 8b-signed-safe weights (disabled radius forced to 0).
        final q0 = params[0][0] > 0
            ? _xq0Vals[rng.nextInt(_xq0Vals.length)]
            : 0;
        final q1 = params[0][1] > 0
            ? _xq1Vals[rng.nextInt(_xq1Vals.length)]
            : 0;
        xq0.add(q0);
        xq1.add(q1);
        epOut.add(ep);
        xqd.add([0, 0]);
      } else {
        final xqd0 = params[0][0] == 0 ? 0 : rng.nextInt(128) - 96; // [-96,31]
        final xqd1 = params[0][1] == 0 ? 0 : rng.nextInt(128) - 32; // [-32,95]
        final xq = _decodeXq([xqd0, xqd1], params);
        xq0.add(xq[0]);
        xq1.add(xq[1]);
        epOut.add(ep);
        xqd.add([xqd0, xqd1]);
      }
    } else {
      rtypes.add(0);
      hf.add([0, 0, 0]);
      vf.add([0, 0, 0]);
      s0.add(0);
      s1.add(0);
      xq0.add(0);
      xq1.add(0);
      epOut.add(-1);
      xqd.add([0, 0]);
    }
  }
  return _Units(rtypes, hf, vf, s0, s1, xq0, xq1, epOut, xqd);
}

