void main() {
  // _swGold holds sw.applyRestorationPlane output (flattened row-major per
  // plane) captured from the SW oracle for the same seed cases/iters (bd 10
  // then 12), so _goldPlane stays validated bit-for-bit against libaom's port.
  test(
    '_goldPlane matches captured applyRestorationPlane golden at bd 10 and 12',
    () {
      var snap = 0;
      for (final bd in [10, 12]) {
        final rng = Random(0xA11 + bd);
        final maxPx = 1 << bd;
        final cases = <List<int>>[
          // [planeW, planeH, unitSize, ssX, ssY]
          [40, 140, 64, 0, 0], // luma, several stripes, >1 unit row
          [72, 96, 64, 0, 0], // luma, multiple unit cols + rows
          [50, 90, 64, 0, 0], // luma, partial last units both axes
          [32, 80, 64, 1, 1], // chroma 420
          [40, 100, 64, 1, 0], // chroma 422 (ssX=1, ssY=0)
        ];
        for (final cfg in cases) {
          final planeW = cfg[0], planeH = cfg[1], unitSize = cfg[2];
          final ssX = cfg[3], ssY = cfg[4];
          for (var iter = 0; iter < 3; iter++) {
            final postCdef = [
              for (var y = 0; y < planeH; y++)
                [for (var x = 0; x < planeW; x++) rng.nextInt(maxPx)],
            ];
            final deblocked = [
              for (var y = 0; y < planeH; y++)
                [for (var x = 0; x < planeW; x++) rng.nextInt(maxPx)],
            ];
            final numUnits =
                _countUnits(unitSize, planeW) * _countUnits(unitSize, planeH);
            final us = _genUnits(rng, numUnits);

            final gold = _goldPlane(
              postCdef,
              deblocked,
              planeW,
              planeH,
              unitSize,
              ssX,
              ssY,
              64,
              8,
              bd,
              us.rtypes,
              us.hf,
              us.vf,
              us.s0,
              us.s1,
              us.xq0,
              us.xq1,
            );

            final want = _swGold[snap++];
            for (var y = 0; y < planeH; y++) {
              for (var x = 0; x < planeW; x++) {
                expect(
                  gold[y][x],
                  equals(want[y * planeW + x]),
                  reason: 'bd=$bd cfg=$cfg iter=$iter (y=$y x=$x)',
                );
              }
            }
          }
        }
      }
    },
  );

  tearDown(() async {
    await Simulator.reset();
  });

  Future<void> runHwCase({
    required int planeW,
    required int planeH,
    required int unitSize,
    required int ssX,
    required int ssY,
    required int procUnitSize,
    required int unitOffset,
    required int bd,
    required int iters,
    required int seed,
    List<int>? eps,
    int? forceRt,
  }) async {
    final frame = HarborLrFrame(
      planeW: planeW,
      planeH: planeH,
      unitSize: unitSize,
      ssX: ssX,
      ssY: ssY,
      procUnitSize: procUnitSize,
      unitOffset: unitOffset,
      bd: bd,
    );
    final numUnits = frame.horzUnits * frame.vertUnits;

    final postCdefP = Logic(name: 'post', width: planeW * planeH * bd);
    final deblockedP = Logic(name: 'deb', width: planeW * planeH * bd);
    final rtypeP = [for (var u = 0; u < numUnits; u++) Logic(width: 2)];
    Logic mk(int w) => Logic(width: w);
    final h0 = [for (var u = 0; u < numUnits; u++) mk(8)];
    final h1 = [for (var u = 0; u < numUnits; u++) mk(8)];
    final h2 = [for (var u = 0; u < numUnits; u++) mk(8)];
    final v0 = [for (var u = 0; u < numUnits; u++) mk(8)];
    final v1 = [for (var u = 0; u < numUnits; u++) mk(8)];
    final v2 = [for (var u = 0; u < numUnits; u++) mk(8)];
    final s0P = [for (var u = 0; u < numUnits; u++) mk(12)];
    final s1P = [for (var u = 0; u < numUnits; u++) mk(12)];
    final xq0P = [for (var u = 0; u < numUnits; u++) mk(8)];
    final xq1P = [for (var u = 0; u < numUnits; u++) mk(8)];

    frame.input('postCdef').srcConnection! <= postCdefP;
    frame.input('deblocked').srcConnection! <= deblockedP;
    for (var u = 0; u < numUnits; u++) {
      frame.input('rtype$u').srcConnection! <= rtypeP[u];
      frame.input('h0_$u').srcConnection! <= h0[u];
      frame.input('h1_$u').srcConnection! <= h1[u];
      frame.input('h2_$u').srcConnection! <= h2[u];
      frame.input('v0_$u').srcConnection! <= v0[u];
      frame.input('v1_$u').srcConnection! <= v1[u];
      frame.input('v2_$u').srcConnection! <= v2[u];
      frame.input('s0_$u').srcConnection! <= s0P[u];
      frame.input('s1_$u').srcConnection! <= s1P[u];
      frame.input('xq0_$u').srcConnection! <= xq0P[u];
      frame.input('xq1_$u').srcConnection! <= xq1P[u];
    }
    await frame.build();

    final clk = SimpleClockGenerator(10).clk;
    Simulator.setMaxSimTime(600000000);
    unawaited(Simulator.run());

    final rng = Random(seed);
    final maxPx = 1 << bd;

    for (var iter = 0; iter < iters; iter++) {
      final postCdef = [
        for (var y = 0; y < planeH; y++)
          [for (var x = 0; x < planeW; x++) rng.nextInt(maxPx)],
      ];
      final deblocked = [
        for (var y = 0; y < planeH; y++)
          [for (var x = 0; x < planeW; x++) rng.nextInt(maxPx)],
      ];
      final us = _genUnits(
        rng,
        numUnits,
        eps: eps,
        forceRt: forceRt,
        hwSafeXq: true,
      );

      postCdefP.put(_packPlane(postCdef, planeW, planeH, bd));
      deblockedP.put(_packPlane(deblocked, planeW, planeH, bd));
      for (var u = 0; u < numUnits; u++) {
        rtypeP[u].put(us.rtypes[u]);
        h0[u].put(BigInt.from(us.hf[u][0]).toUnsigned(8));
        h1[u].put(BigInt.from(us.hf[u][1]).toUnsigned(8));
        h2[u].put(BigInt.from(us.hf[u][2]).toUnsigned(8));
        v0[u].put(BigInt.from(us.vf[u][0]).toUnsigned(8));
        v1[u].put(BigInt.from(us.vf[u][1]).toUnsigned(8));
        v2[u].put(BigInt.from(us.vf[u][2]).toUnsigned(8));
        s0P[u].put(us.s0[u]);
        s1P[u].put(us.s1[u]);
        xq0P[u].put(BigInt.from(us.xq0[u]).toUnsigned(8));
        xq1P[u].put(BigInt.from(us.xq1[u]).toUnsigned(8));
      }
      await clk.nextPosedge;

      final gold = _goldPlane(
        postCdef,
        deblocked,
        planeW,
        planeH,
        unitSize,
        ssX,
        ssY,
        procUnitSize,
        unitOffset,
        bd,
        us.rtypes,
        us.hf,
        us.vf,
        us.s0,
        us.s1,
        us.xq0,
        us.xq1,
      );
      final out = frame.output('out').value;
      for (var y = 0; y < planeH; y++) {
        for (var x = 0; x < planeW; x++) {
          final k = y * planeW + x;
          expect(
            out.getRange(k * bd, k * bd + bd).toInt(),
            equals(gold[y][x]),
            reason: 'bd=$bd iter=$iter (y=$y x=$x)',
          );
        }
      }
    }
    await Simulator.endSimulation();
  }

  for (final bd in [10, 12]) {
    test(
      'HarborLrFrame Wiener luma bit-exact (bd=$bd)',
      () async {
        await runHwCase(
          planeW: 8,
          planeH: 16,
          unitSize: 16,
          ssX: 0,
          ssY: 0,
          procUnitSize: 8,
          unitOffset: 2,
          bd: bd,
          iters: 3,
          seed: 0x71 ^ bd,
          forceRt: 1,
        );
      },
      timeout: const Timeout(Duration(minutes: 4)),
    );

    test(
      'HarborLrFrame SGR luma all-regimes bit-exact (bd=$bd)',
      () async {
        // eps sweep: 0 (r0>0&r1>0), 10 (r0==0), 14 (r1==0).
        await runHwCase(
          planeW: 8,
          planeH: 16,
          unitSize: 16,
          ssX: 0,
          ssY: 0,
          procUnitSize: 8,
          unitOffset: 2,
          bd: bd,
          iters: 3,
          seed: 0x53 ^ bd,
          eps: [0, 10, 14],
          forceRt: 2,
        );
      },
      timeout: const Timeout(Duration(minutes: 6)),
    );

    test(
      'HarborLrFrame chroma 420 mixed bit-exact (bd=$bd)',
      () async {
        await runHwCase(
          planeW: 6,
          planeH: 12,
          unitSize: 8,
          ssX: 1,
          ssY: 1,
          procUnitSize: 8,
          unitOffset: 2,
          bd: bd,
          iters: 3,
          seed: 0xC4 ^ bd,
          eps: [0, 10, 14],
        );
      },
      timeout: const Timeout(Duration(minutes: 6)),
    );
  }

  test(
    'HarborLrFrame chroma 422 (ssX=1, ssY=0) bit-exact (bd=8)',
    () async {
      await runHwCase(
        planeW: 6,
        planeH: 12,
        unitSize: 8,
        ssX: 1,
        ssY: 0,
        procUnitSize: 8,
        unitOffset: 2,
        bd: 8,
        iters: 4,
        seed: 0x422,
        eps: [0, 10, 14],
      );
    },
    timeout: const Timeout(Duration(minutes: 6)),
  );
}
